package com.smarthrms.service;
import com.smarthrms.dto.AuthDtos.*; import com.smarthrms.exception.ApiException; import com.smarthrms.repository.UserRepository; import com.smarthrms.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public LoginResponse login(LoginRequest req){var u=users.findByEmailIgnoreCase(req.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password")); if(!u.isEnabled()||!encoder.matches(req.password(),u.getPassword())) throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"); return new LoginResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name());}}
